  const mid = Math.floor((lo + hi) / 2);
  return binarySumImpl(arr, lo, mid) + binarySumImpl(arr, mid + 1, hi);
}

function factorialTailImpl(n, accumulator = 1) {
  if (n <= 1) return accumulator;
  return factorialTailImpl(n - 1, n * accumulator);
