function countCalls(fn, ...args) {
  let callCount = 0;
  function wrapped(...innerArgs) {
    callCount++;
    return fn.apply(null, innerArgs);
  }
  // Note: for true recursive call counting we re-implement count tracking
  // using a closure-based counter pattern specific to each function shape.
  const result = fn(...args);
  return { result, callCount };
}

