function fibNaiveImpl(n) {
  if (n <= 1) return n;
  return fibNaiveImpl(n - 1) + fibNaiveImpl(n - 2);
}

function fibMemoImpl(n, cache = new Map()) {
  if (n <= 1) return n;
  if (cache.has(n)) return cache.get(n);
  const result = fibMemoImpl(n - 1, cache) + fibMemoImpl(n - 2, cache);
  cache.set(n, result);
  return result;
}

function fibBottomUpImpl(n) {
  if (n <= 1) return n;
  const dp = new Array(n + 1);
  dp[0] = 0; dp[1] = 1;
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}

function fibOptimalImpl(n) {
  if (n <= 1) return n;
  let prev2 = 0, prev1 = 1;
  for (let i = 2; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

function memoizeImpl(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

function countPathsRaw(m, n) {
  if (m === 1 || n === 1) return 1;
  return countPathsRaw(m - 1, n) + countPathsRaw(m, n - 1);
}

