function mergeSortImpl(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSortImpl(arr.slice(0, mid));
  const right = mergeSortImpl(arr.slice(mid));
  return mergeImpl(left, right);
}

function mergeImpl(left, right) {
  const result = [];
  let l = 0, r = 0;
  while (l < left.length && r < right.length) {
    if (left[l] <= right[r]) {
      result.push(left[l++]);
    } else {
      result.push(right[r++]);
    }
  }
  while (l < left.length) result.push(left[l++]);
  while (r < right.length) result.push(right[r++]);
  return result;
}

function countInversionsImpl(arr) {
  if (arr.length <= 1) return { sorted: arr, count: 0 };
  const mid = Math.floor(arr.length / 2);
  const { sorted: L, count: lc } = countInversionsImpl(arr.slice(0, mid));
  const { sorted: R, count: rc } = countInversionsImpl(arr.slice(mid));
  let count = lc + rc, l = 0, r = 0;
  const sorted = [];
  while (l < L.length && r < R.length) {
    if (L[l] <= R[r]) { sorted.push(L[l++]); }
    else { sorted.push(R[r++]); count += L.length - l; }
  }
  while (l < L.length) sorted.push(L[l++]);
  while (r < R.length) sorted.push(R[r++]);
  return { sorted, count };
}

function bruteForceInversions(arr) {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] > arr[j]) count++;
    }
  }
  return count;
}

function verifyInversionCount(arr) {
  return countInversionsImpl(arr).count === bruteForceInversions(arr);
}

