function quickSortImpl(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;
  const pivotIdx = partitionImpl(arr, lo, hi);
  quickSortImpl(arr, lo, pivotIdx - 1);
  quickSortImpl(arr, pivotIdx + 1, hi);
}

function partitionImpl(arr, lo, hi) {
  const randIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[randIdx], arr[hi]] = [arr[hi], arr[randIdx]];
  const pivot = arr[hi];
  let i = lo - 1;
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];
  return i + 1;
}

function quickSortBadImpl(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;
  const pIdx = partitionNoRandImpl(arr, lo, hi);
  quickSortBadImpl(arr, lo, pIdx - 1);
  quickSortBadImpl(arr, pIdx + 1, hi);
}

function partitionNoRandImpl(arr, lo, hi) {
  const pivot = arr[hi];
  let i = lo - 1;
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];
  return i + 1;
}

function compareSortedInputPerformance(size) {
  const sorted = Array.from({length: size}, (_, i) => i);
  const a1 = [...sorted], a2 = [...sorted];
