function countingSortImpl(arr, maxVal) {
  const count = new Array(maxVal + 1).fill(0);
  for (const val of arr) count[val]++;
  const result = [];
  for (let val = 0; val <= maxVal; val++) {
    for (let c = 0; c < count[val]; c++) result.push(val);
  }
  return result;
}

function countingSortStableImpl(arr, maxVal) {
  const count = new Array(maxVal + 1).fill(0);
  for (const val of arr) count[val]++;
  for (let i = 1; i <= maxVal; i++) count[i] += count[i - 1];
  const output = new Array(arr.length);
  for (let i = arr.length - 1; i >= 0; i--) {
    output[--count[arr[i]]] = arr[i];
  }
  return output;
}

function bucketSortImpl(arr) {
  const n = arr.length;
  const buckets = Array.from({length: n}, () => []);
  for (const x of arr) {
    const idx = Math.floor(x * n);
    buckets[Math.min(idx, n - 1)].push(x);
  }
  for (const b of buckets) b.sort((a, c) => a - c);
  return [].concat(...buckets);
}

function recommendSortingAlgorithm(description) {
  const map = {
    bounded_integers: 'Counting Sort',
    uniform_floats: 'Bucket Sort',
    general_comparison: 'Merge Sort or Quicksort'
  };
  return map[description];
}

