const sortingAlgorithms = [
  { name: 'Bubble Sort', timeWorst: 'O(n\u00b2)', timeAvg: 'O(n\u00b2)', timeBest: 'O(n)', space: 'O(1)', stable: true },
  { name: 'Selection Sort', timeWorst: 'O(n\u00b2)', timeAvg: 'O(n\u00b2)', timeBest: 'O(n\u00b2)', space: 'O(1)', stable: false },
  { name: 'Insertion Sort', timeWorst: 'O(n\u00b2)', timeAvg: 'O(n\u00b2)', timeBest: 'O(n)', space: 'O(1)', stable: true },
  { name: 'Merge Sort', timeWorst: 'O(n log n)', timeAvg: 'O(n log n)', timeBest: 'O(n log n)', space: 'O(n)', stable: true },
  { name: 'Quick Sort', timeWorst: 'O(n\u00b2)', timeAvg: 'O(n log n)', timeBest: 'O(n log n)', space: 'O(log n)', stable: false },
  { name: 'Heap Sort', timeWorst: 'O(n log n)', timeAvg: 'O(n log n)', timeBest: 'O(n log n)', space: 'O(1)', stable: false },
  { name: 'Counting Sort', timeWorst: 'O(n+k)', timeAvg: 'O(n+k)', timeBest: 'O(n+k)', space: 'O(k)', stable: true },
  { name: 'TimSort (JS default)', timeWorst: 'O(n log n)', timeAvg: 'O(n log n)', timeBest: 'O(n)', space: 'O(n)', stable: true },
];

function getAlgorithmInfo(name) {
  return sortingAlgorithms.find(a => a.name === name);
}

function filterByStability(stableOnly) {
  return sortingAlgorithms.filter(a => a.stable === stableOnly).map(a => a.name);
}

function filterBySpace(maxSpaceClass) {
  return sortingAlgorithms.filter(a => a.space === maxSpaceClass).map(a => a.name);
}

function recommendForRequirements({ needsStability, needsConstantSpace }) {
  const match = sortingAlgorithms.find(a => {
    if (needsStability && !a.stable) return false;
    if (needsConstantSpace && a.space !== 'O(1)') return false;
    return true;
  });
  return match ? match.name : null;
}

