function classifyApproach(signals) {
  const s = new Set(signals);
  if (s.has('overlapping_subproblems')) return 'Memoized Recursion';
  if (s.has('bounded_integer_range')) return 'Linear Sort (Counting/Bucket)';
  if (s.has('general_unordered')) return 'Comparison Sort (Merge/Quick)';
  if (s.has('sorted_array_search')) return 'Binary Search';
  if (s.has('minimize_maximize_with_feasibility_check')) return 'Binary Search On Answer';
  return 'Unknown';
}

function maxCutLengthImpl(ropes, k) {
  let lo = 1, hi = Math.max(...ropes);
  let result = 0;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    const pieces = ropes.reduce((sum, r) => sum + Math.floor(r / mid), 0);
    if (pieces >= k) {
      result = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return result;
}

function minDaysToShipPackages(weights, days) {
  function daysNeeded(capacity) {
    let dayCount = 1, currentLoad = 0;
    for (const w of weights) {
      if (currentLoad + w > capacity) {
        dayCount++;
        currentLoad = 0;
      }
      currentLoad += w;
    }
    return dayCount;
  }
  let lo = Math.max(...weights), hi = weights.reduce((a,b) => a+b, 0);
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (daysNeeded(mid) <= days) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}
